result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/username.test.mjs", "content": "import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Worker } from 'node:worker_threads';

function runInWorker(code, timeoutMs = 2000) {
  return new Promise((resolve, reject) => {
    const worker = new Worker(code, { eval: true });
    const timer = setTimeout(() => {
      worker.terminate();
      reject(new Error(`Watchdog: no result within ${timeoutMs}ms (possible catastrophic backtracking)`));
    }, timeoutMs);
    worker.on('message', (msg) => {
      clearTimeout(timer);
      worker.terminate();
      resolve(msg);
    });
    worker.on('error', (err) => {
      clearTimeout(timer);
      reject(err);
    });
  });
}

test('catastrophic backtracking: hostile input must not hang', async () => {
  const code = `
    const { parentPort } = require('node:worker_threads');
    import('./username.mjs').then(({ isValidUsername }) => {
      const result = isValidUsername('a'.repeat(40) + '!');
      parentPort.postMessage({ result });
    });
  `;
  await assert.rejects(runInWorker(code), /Watchdog/);
});

test('fixed validator: accept/reject table', async () => {
  const { isValidUsername } = await import('./username.mjs');
  const cases = [
    // accepts
    ['a', true],
    ['a_b', true],
    ['a-b-c', true],
    ['abc123', true],
    ['a_1-b_2', true],
    ['x'.repeat(64), true],
    // rejects
    ['a__b', false],
    ['a--b', false],
    ['a_-b', false],
    ['_a', false],
    ['-a', false],
    ['a_', false],
    ['a-', false],
    ['', false],
    ['!', false],
    ['ab!cd', false],
    ['x'.repeat(65), false],
  ];
  for (const [input, expected] of cases) {
    assert.equal(isValidUsername(input), expected, `isValidUsername(${JSON.stringify(input)})`);
  }
});
"})
print(result)

result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/username.mjs", "content": "// Linear-time username validation.
//
// Old (vulnerable): /^([a-zA-Z0-9]+[_-]?)+$/
//   Nested quantifiers ((...)+ around X+Y?) let the engine try exponentially
//   many ways to split the input among outer repetitions. On failure it
//   backtracks catastrophically: 'a'.repeat(40) + '!' never terminates.
//   It also accepted trailing separators ('a_', 'a-').
//
// Fix:
//   1. Cheap length check first (O(1), rejects oversized input outright).
//   2. Unambiguous single-pass pattern with no nested quantifiers:
//      ^[a-zA-Z0-9]+([_-][a-zA-Z0-9]+)*$
//      Each [a-zA-Z0-9]+ run is consumed exactly once; [_-] is mandatory
//      between runs, so no ambiguity -> linear time.
const RE = /^[a-zA-Z0-9]+([_-][a-zA-Z0-9]+)*$/;

export function isValidUsername(s) {
  return typeof s === 'string' && s.length <= 64 && RE.test(s);
}
"})
print(result)

