// Run: node demo-hang.mjs
import { Worker } from 'node:worker_threads';

const VULNERABLE = /^([a-zA-Z0-9]+[_-]?)+$/;

const worker = new Worker(
  `(const { parentPort } = require('node:worker_threads');
    const RE = /^([a-zA-Z0-9]+[_-]?)+$/;
    const t0 = Date.now();
    const r = RE.test('a'.repeat(40) + '!');
    parentPort.postMessage({ result: r, ms: Date.now() - t0 });`,
  { eval: true }
);

const timer = setTimeout(() => {
  console.log(`HANG CONFIRMED: no result within 2000ms — terminating worker.`);
  worker.terminate().then(() => process.exit(1));
}, 2000);

worker.on('message', ({ result, ms }) => {
  clearTimeout(timer);
  console.log(`Completed in ${ms}ms, result=${result} (no hang?)`);
  process.exit(0);
});
"})
print(result)

